export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  const org = await orgRepo.findOrgBySlug(slug);
  if (!org || org.archivedAt !== null) return null;
  return org;
}

/** Drops every delivery still waiting, so a closed workspace cannot send them. */
export async function failPendingDeliveries(
  orgId: OrgId,
  error: string,
): Promise<void> {
  getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.status, "pending"),
      ),
    )
    .run();
}

