/**
 * A second close never reaches `withAction`: actor resolution refuses a
 * closed workspace, and this path is what still reports the conflict.
 */
async function resultIfClosed(
  input: DeleteOrganizationInput,
): Promise<ActionResult<Organization> | null> {
  const org = await orgRepo.findOrgById(input.orgId);
  if (!org || org.archivedAt === null) return null;

  const principal = await getSessionPrincipal();
  if (principal === null) return toActionResult(new UnauthorizedActionError());

  const member = await memberRepo.findMember(org.id, principal.userId);
